import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long num = scanner.nextLong();
        long den = scanner.nextLong();
        long limit = scanner.nextLong();

        int bestNumerator = 0;
        int bestDenominator = 1;

        for (int i = 1; i <= limit; ++i) {
            long q = (num * i) / den;
            long diff1 = num * i - q * den;
            long diff2 = (q + 1) * den - num * i;
            if (diff1 > diff2) q++;
            if (Math.abs(bestDenominator * (num * i - q * den)) < Math.abs(i * (num * bestDenominator - den * bestNumerator))) {
                bestNumerator = (int) q;
                bestDenominator = i;
            }
        }
        System.out.println(bestNumerator + "/" + bestDenominator);
        scanner.close();
    }
}
